const cb = $input.item.json.callback_query;
const replyMsg = cb.message?.reply_to_message;

// 1. Get file_id from the original user photo or document
const file_id = replyMsg?.document?.file_id || replyMsg?.photo?.slice(-1)[0]?.file_id;

// 2. Parse details from the message text
const text = cb.message?.text || '';

const getField = (regex) => {
  const match = text.match(regex);
  return match ? match[1].trim() : '';
};

const docTypeMatch = text.match(/Document Type:\s*(.+)/i);
const docType = docTypeMatch ? docTypeMatch[1].trim() : 'Unknown';

const fields = {
  name: getField(/Name:\s*(.+)/i),
  phone: getField(/Phone:\s*(.+)/i),
  email: getField(/Email:\s*(.+)/i),
  title_designation: getField(/Designation:\s*(.+)/i),
  company: getField(/Company:\s*(.+)/i),
  website: getField(/Website:\s*(.+)/i),
  address: getField(/Address:\s*(.+)/i),
  id_number: getField(/ID Number:\s*(.+)/i),
  dob: getField(/DOB:\s*(.+)/i),
  father_name: getField(/Father's Name:\s*(.+)/i)
};

return {
  json: {
    file_id: file_id,
    chat_id: cb.message.chat.id,
    user_name: cb.from.first_name || 'User',
    docType: docType,
    fields: fields
  }
};

