const cb = $input.item.json.callback_query;
const replyMsg = cb.message?.reply_to_message;

// 1. Get file_id from original message
const file_id = replyMsg?.document?.file_id || replyMsg?.photo?.slice(-1)[0]?.file_id;

// 2. Parse text fields from the confirmation message
const text = cb.message?.text || '';

const getField = (regex) => {
  const match = text.match(regex);
  if (!match || !match[1]) return '';
  const val = match[1].trim();
  return val === 'N/A' ? '' : val;
};

const docTypeMatch = text.match(/Document Type:\s*=?([^\n]+)/i);
const docType = docTypeMatch ? docTypeMatch[1].trim().replace(/^=/, '') : 'Unknown';

const fields = {
  name: getField(/Name:\s*([^\n]+)/i),
  phone: getField(/Phone:\s*([^\n]+)/i),
  email: getField(/Email:\s*([^\n]+)/i),
  title_designation: getField(/Designation:\s*([^\n]+)/i),
  company: getField(/Company:\s*([^\n]+)/i),
  website: getField(/Website:\s*([^\n]+)/i),
  address: getField(/Address:\s*([^\n]+)/i),
  id_number: getField(/(?:ID Number|PAN Number|License Number):\s*([^\n]+)/i),
  dob: getField(/(?:DOB|DOB \/ Year of Birth):\s*([^\n]+)/i),
  father_name: getField(/Father's Name:\s*([^\n]+)/i)
};

return {
  json: {
    file_id: file_id,
    chat_id: cb.message.chat.id,
    user_name: cb.from?.first_name || 'User',
    docType: docType,
    fields: fields
  }
};

const rawText = $input.item.json.content?.parts?.[0]?.text || $input.item.json.text || '{}';
const cleanText = rawText.replace(/```json|```/g, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(cleanText);
} catch (e) {
  parsed = { docType: 'Unknown', data: {} };
}

const telegramMsg = $('Telegram Trigger2').item.json.message;

return {
  json: {
    chat_id: telegramMsg.chat.id,
    message_id: telegramMsg.message_id,
    identified_type: parsed.docType || 'Unknown',
    extracted_data: parsed,
    data: parsed.data || {}
  }
};

